window.__votdWeek && window.__votdWeek({"week":"2029-10-29","reading":"Doctrine and Covenants 124","days":[{"d":"2029-10-29","ref":"D&C 124:11","b":"D&C","c":124,"v":11,"he":"הָקִיצוּ מַלְכֵי אָרֶץ בֹּאוּ בֹאוּ בִּזְהַבְכֶם וּבְכַסְפְּכֶם לְעֶזְרַת עַמִּי לְבֵית בְּנוֹת צִיּוֹן׃","en":"Awake, O kings of the earth! Come ye, O, come ye, with your gold and your silver, to the help of my people, to the house of the daughters of Zion."},{"d":"2029-10-30","ref":"D&C 124:27","b":"D&C","c":124,"v":27,"he":"וּבְבַרְזֶל וּבִנְחוּשָׁה וּבְעֶשֶׁת וּבְאָבָץ וּבְכׇל־דִּבְרֵי יְקַרְכֶם אֲשֶׁר בָּאָרֶץ וּבְנוּ בַּיִת לִשְׁמִי לְמַעַן יִשְׁכֹּן בּוֹ עֶלְיוֹן׃","en":"And with iron, with copper, and with brass, and with zinc, and with all your precious things of the earth; and build a house to my name, for the Most High to dwell therein."},{"d":"2029-10-31","ref":"D&C 124:31","b":"D&C","c":124,"v":31,"he":"אַךְ אֲנִי מְצַוֶּה אֶתְכֶם כׇּל־קְדוֹשַׁי לִבְנוֹת בַּיִת לִי וַאֲנִי נֹתֵן לָכֶם זְמַן דַּי לִבְנוֹתוֹ וּבָעֵת הַזֹּאת טְבִילוֹתֵיכֶם רְצוּיוֹת לִי׃","en":"But I command you, all ye my saints, to build a house unto me; and I grant unto you a sufficient time to build a house unto me; and during this time your baptisms shall be acceptable unto me."},{"d":"2029-11-01","ref":"D&C 124:41","b":"D&C","c":124,"v":41,"he":"כִּי חָפַצְתִּי לְגַלּוֹת לִכְנֵסִיָּתִי דְּבָרִים הַנִּסְתָּרִים מִלִּפְנֵי יְסוֹד הָעוֹלָם אֲשֶׁר לִתְקוּפַת מְלֹא הָעִתִּים׃","en":"For I deign to reveal unto my church things which have been kept hid from before the foundation of the world, things that pertain to the dispensation of the fulness of times."},{"d":"2029-11-02","ref":"D&C 124:51","b":"D&C","c":124,"v":51,"he":"לָכֵן קִבַּלְתִּי אֶת־קָרְבְּנוֹת אֵלֶּה אֲשֶׁר צִוִּיתִים לִבְנוֹת עִיר וּבַיִת לִשְׁמִי בִּמְחוֹז גָ׳קְסוֹן מִיזוּרִי וְעֻכְּבוּ עַל יְדֵי אֹיְבֵיהֶם נְאֻם יְהוָה אֱלֹהֵיכֶם׃","en":"Therefore, for this cause have I accepted the offerings of those whom I commanded to build up a city and a house unto my name, in Jackson county, Missouri, and were hindered by their enemies, saith the Lord your God."},{"d":"2029-11-03","ref":"D&C 124:99","b":"D&C","c":124,"v":99,"he":"וּבִנְתִיבוֹת אֲשֶׁר הַנָּחָשׁ הָאָרְסִי לֹא יוּכַל לְהַשִּׂיג עֲקֵבוֹ יוּבַל וְיַעֲלֶה בְּמַחְשְׁבוֹתָיו כְּעַל כַּנְפֵי נְשָׁרִים׃","en":"And he shall be led in paths where the poisonous serpent cannot lay hold upon his heel, and he shall mount up in the imagination of his thoughts as upon eagles' wings."},{"d":"2029-11-04","ref":"D&C 124:114","b":"D&C","c":124,"v":114,"he":"לָכֵן יַשְׁפִּיל עַצְמוֹ לְמַעַן יְרוּמָם כֵּן אָמֵן׃","en":"Let him therefore abase himself that he may be exalted. Even so. Amen."}]});
